import { Injectable, inject } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Observable, map } from 'rxjs';
import {
  AprobarMachotePayload,
  Machote,
  MachoteMutationResponse,
} from '../models/machote.model';
import { environment } from '../../../environments/environment';

@Injectable({ providedIn: 'root' })
export class MachoteService {
  private readonly http = inject(HttpClient);
  private readonly apiUrl = environment.apiUrl;

  generar(folio: string): Observable<Machote> {
    return this.http
      .post<{ data: Machote }>(
        `${this.apiUrl}/solicitudes/${folio}/machotes/generar`,
        {},
      )
      .pipe(map((res) => res.data));
  }

  listar(folio: string): Observable<Machote[]> {
    return this.http
      .get<{ data: Machote[] }>(`${this.apiUrl}/solicitudes/${folio}/machotes`)
      .pipe(map((res) => res.data));
  }

  aprobar(
    folio: string,
    machoteId: number,
    payload: AprobarMachotePayload,
  ): Observable<MachoteMutationResponse> {
    return this.http.post<MachoteMutationResponse>(
      `${this.apiUrl}/solicitudes/${folio}/machotes/${machoteId}/aprobar`,
      payload,
    );
  }

  firmar(
    folio: string,
    machoteId: number,
    signedPdf: Uint8Array | Blob,
    firmaSerial?: string,
    firmaMetadata?: string,
  ): Observable<MachoteMutationResponse> {
    const formData = new FormData();
    const blob =
      signedPdf instanceof Blob
        ? signedPdf
        : new Blob([new Uint8Array(signedPdf)], { type: 'application/pdf' });
    formData.append('signed_pdf', blob, 'machote_firmado.pdf');
    if (firmaSerial) {
      formData.append('firma_serial', firmaSerial);
    }
    if (firmaMetadata) {
      formData.append('firma_metadata', firmaMetadata);
    }
    return this.http.post<MachoteMutationResponse>(
      `${this.apiUrl}/solicitudes/${folio}/machotes/${machoteId}/firmar`,
      formData,
    );
  }
}
